# shellcheck shell=sh
# OpenWrt Roaming Manager - roaming validator
#
# Verifies what hostapd is *actually running with*, not what UCI says:
#  * the hostapd configuration generated by netifd (/var/run/hostapd-*.conf)
#    for the BSS: AKMs, mobility_domain, ft_* , r0kh/r1kh, rrm_*, bss_transition
#  * the running daemon over ubus: BSS present, own neighbor report,
#    installed neighbor list, WNM methods

# Print "key=value" lines of the hostapd.conf block that belongs to IFNAME
hv_conf_block() {
	local _ifn _f
	_ifn=$1
	for _f in "$(orm_path /var/run)"/hostapd-*.conf; do
		[ -f "$_f" ] || continue
		awk -v ifn="$_ifn" '
			/^(interface|bss)=/ { cur = $0; sub(/^(interface|bss)=/, "", cur) }
			cur == ifn && /^[a-z0-9_]+=/ { print }
		' "$_f"
	done
}

hv_conf_get() {
	# hv_conf_get BLOCK KEY
	printf '%s\n' "$1" | sed -n "s/^$2=//p" | head -n1
}

# Validate one interface. Writes report entries; returns 1 on FAIL.
# hv_validate_iface SECTION GROUP
hv_validate_iface() {
	local _s _g _if _label _fail _blk _have_conf _want_r _md _akm _rmd _miss _a _km _r0 _r1 _k _ods _want_k _nrown _b _want _have _bcn _want_v _m
	_s=$1 _g=$2
	_if=$(caps_get "iface.$_s.ifname")
	_label="$_s${_if:+ ($_if)}"
	_fail=0
	if [ -z "$_if" ] || [ "$(caps_get "iface.$_s.hostapd")" != 1 ]; then
		report_add hostapd "$_label" FAIL "BSS is not running in hostapd"
		return 1
	fi
	report_add hostapd "$_label" PASS "BSS active in hostapd"
	_blk=$(hv_conf_block "$_if")
	_have_conf=1
	[ -n "$_blk" ] || _have_conf=0

	# ---- 802.11r
	_want_r=$(roam_get "$_g.ieee80211r" 0)
	if [ "$_want_r" = 1 ] && [ "$(caps_get "iface.$_s.can_11r")" = 1 ]; then
		_md=$(roam_get "$_g.mdid")
		if [ "$_have_conf" = 0 ]; then
			report_add 11r "$_label" WARN "hostapd runtime configuration not readable; FT verified from UCI only"
		else
			_akm=$(hv_conf_get "$_blk" wpa_key_mgmt)
			_rmd=$(lower "$(hv_conf_get "$_blk" mobility_domain)")
			_miss=''
			for _a in $(r_expected_akm "$(caps_get "iface.$_s.security")"); do
				list_contains "$_akm" "$_a" || _miss="$_miss $_a"
			done
			if [ "$_rmd" != "$_md" ]; then
				report_add 11r "$_label" FAIL "hostapd mobility_domain='${_rmd:-unset}', expected $_md"
				_fail=1
			elif [ -n "$_miss" ]; then
				report_add 11r "$_label" FAIL "AKM${_miss} missing from wpa_key_mgmt ($_akm)"
				_fail=1
			else
				_km=$(roam_get "$_g.ft_key_mode" local)
				if [ "$_km" = local ]; then
					if [ "$(hv_conf_get "$_blk" ft_psk_generate_local)" = 1 ]; then
						report_add 11r "$_label" PASS "FT active (MDID $_md, $_akm, PSK-local key derivation)"
					else
						report_add 11r "$_label" WARN "FT active but ft_psk_generate_local not set in hostapd"
					fi
				else
					_r0=$(printf '%s\n' "$_blk" | grep -c '^r0kh=')
					_r1=$(printf '%s\n' "$_blk" | grep -c '^r1kh=')
					_k=$(printf '%s\n' "$_blk" | sed -n 's/^r0kh=[^ ]* [^ ]* //p' | head -n1)
					if [ "$_r0" -ge 1 ] && [ "$_r1" -ge 1 ] && [ "$(secret_fingerprint "$_k")" = "$(ft_key_fingerprint "$_g")" ]; then
						report_add 11r "$_label" PASS "FT active (MDID $_md, $_akm, R0KH/R1KH key consistent)"
					else
						report_add 11r "$_label" FAIL "R0KH/R1KH entries missing or key mismatch in hostapd"
						_fail=1
					fi
				fi
				_ods=$(hv_conf_get "$_blk" ft_over_ds)
				caps_set "iface.$_s.run_ft_over_ds" "${_ods:-1}"
			fi
		fi
	elif [ "$_want_r" = 1 ]; then
		report_add 11r "$_label" "NOT SUPPORTED" "$(caps_get "iface.$_s.why_11r")"
	fi

	# ---- 802.11k
	_want_k=$(roam_get "$_g.ieee80211k" 0)
	if [ "$_want_k" = 1 ] && [ "$(caps_get "iface.$_s.can_11k")" = 1 ]; then
		_nrown=$(nr_own "$_if" 2>/dev/null)
		if [ "$_have_conf" = 1 ] && [ "$(hv_conf_get "$_blk" rrm_neighbor_report)" != 1 ]; then
			report_add 11k "$_label" FAIL "rrm_neighbor_report not enabled in running hostapd"
			_fail=1
		elif [ -z "$_nrown" ]; then
			report_add 11k "$_label" FAIL "hostapd returns no own neighbor report"
			_fail=1
		else
			_b=$(caps_get "iface.$_s.bssid")
			_want=$(nr_count_for "$_g" "$_b")
			_have=$(nr_installed_count "$_if")
			_bcn=''
			[ "$_have_conf" = 1 ] && [ "$(hv_conf_get "$_blk" rrm_beacon_report)" = 1 ] && _bcn=", beacon report"
			if [ "$_want" -eq 0 ]; then
				report_add 11k "$_label" PASS "RRM active (neighbor report${_bcn}); no other BSS in group yet"
			elif [ "$_have" -ge "$_want" ]; then
				report_add 11k "$_label" PASS "RRM active (neighbor report${_bcn}); $_have neighbor(s) installed"
			elif [ "$(nr_effective_mode)" = backend ]; then
				report_add 11k "$_label" WARN "RRM active; steering backend has installed $_have of $_want known neighbors"
			else
				report_add 11k "$_label" FAIL "only $_have of $_want neighbor entries installed in hostapd"
				_fail=1
			fi
		fi
	elif [ "$_want_k" = 1 ]; then
		report_add 11k "$_label" "NOT SUPPORTED" "$(caps_get "iface.$_s.why_11k")"
	fi

	# ---- 802.11v
	_want_v=$(roam_get "$_g.ieee80211v" 0)
	if [ "$_want_v" = 1 ] && [ "$(caps_get "iface.$_s.can_11v")" = 1 ]; then
		_m=$(compat_bss_methods "$_if" | tr '\n' ' ')
		if [ "$_have_conf" = 1 ] && [ "$(hv_conf_get "$_blk" bss_transition)" != 1 ]; then
			report_add 11v "$_label" FAIL "bss_transition not enabled in running hostapd"
			_fail=1
		elif list_contains "$_m" bss_transition_request; then
			report_add 11v "$_label" PASS "BSS Transition Management active (BTM request available)"
		elif list_contains "$_m" wnm_disassoc_imminent; then
			report_add 11v "$_label" WARN "BTM advertised; hostapd only offers disassoc-imminent requests"
		else
			report_add 11v "$_label" FAIL "hostapd exports no BTM methods"
			_fail=1
		fi
	elif [ "$_want_v" = 1 ]; then
		report_add 11v "$_label" "NOT SUPPORTED" "$(caps_get "iface.$_s.why_11v")"
	fi
	return $_fail
}

hv_validate_all() {
	local _rc _g _s
	_rc=0
	for _g in $(roam_groups); do
		for _s in $(roam_get "$_g.iface"); do
			hv_validate_iface "$_s" "$_g" || _rc=1
		done
	done
	return $_rc
}
